<script lang="ts">import type{EditorStore}from'../store.js';import type{PrinterSdk}from'../print/types.js';import{addElement,addFont,addResource}from'../commands.js';import{importAsset,importFont}from'../imports.js';import{uuid}from'../model.js';import{AssetCatalogue,type CatalogueAsset}from'../catalogue.js';import manifest from'../../../assets/public-catalogue.json';export let editor:EditorStore;export let sdk:PrinterSdk|undefined=undefined;let query='';let category='';let status='';let privateAssets:CatalogueAsset[]=[];let favorites=new Set<string>(JSON.parse(localStorage.getItem('mb-asset-favorites')??'[]'));let recents:string[]=JSON.parse(localStorage.getItem('mb-asset-recents')??'[]');$:catalogue=new AssetCatalogue([...(manifest as CatalogueAsset[]).filter(item=>item.visibility==='public'),...privateAssets]);$:results=catalogue.search({query,category:category||undefined}).sort((a,b)=>recents.indexOf(b.id)-recents.indexOf(a.id));
function remember(id:string){recents=[id,...recents.filter(item=>item!==id)].slice(0,12);localStorage.setItem('mb-asset-recents',JSON.stringify(recents))}function favorite(id:string){favorites=new Set(favorites);favorites.has(id)?favorites.delete(id):favorites.add(id);localStorage.setItem('mb-asset-favorites',JSON.stringify([...favorites]))}function use(item:CatalogueAsset){if(!item.dataBase64)return;const resource={id:uuid(),name:item.name,mimeType:item.mediaType,sha256:item.sha256,data:item.dataBase64};editor.execute(addResource(resource));editor.execute(addElement({id:uuid(),name:item.name,type:'svg',resourceId:resource.id,transform:{x:2,y:2,width:20,height:20,rotation:0},zIndex:$editor.document.elements.length,visible:true,locked:false}));remember(item.id);status=`Added ${item.name}`}async function collection(event:Event){try{const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;const value=JSON.parse(await file.text())as CatalogueAsset[]|{assets:CatalogueAsset[]};privateAssets=(Array.isArray(value)?value:value.assets).map(item=>({...item,visibility:'private',redistributionStatus:'private-only'}));status=`Loaded ${privateAssets.length} private collection assets locally.`}catch(error){status=String(error)}}async function asset(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(!file)return;try{const imported=await importAsset(file,sdk);editor.execute(addResource(imported.resource));status=`Imported ${file.name}`}catch(error){status=String(error)}}async function font(event:Event){const file=(event.currentTarget as HTMLInputElement).files?.[0];if(file)editor.execute(addFont(await importFont(file)))}</script>
<section><h2>Asset catalogue</h2><input type="search" bind:value={query} placeholder="Search catalogue"><select bind:value={category}><option value="">All categories</option>{#each catalogue.categories as item}<option>{item}</option>{/each}</select><div class="actions"><label>Image/SVG/PDF<input type="file" accept="image/*,.svg,application/pdf" on:change={asset}></label><label>Font<input type="file" accept=".woff,.woff2,.ttf,.otf" on:change={font}></label><label>Private .mb-assets<input type="file" accept=".mb-assets,application/json" on:change={collection}></label></div><p aria-live="polite">{status}</p><ul>{#each results as item}<li><button class="star" aria-label={`Favorite ${item.name}`} aria-pressed={favorites.has(item.id)} on:click={()=>favorite(item.id)}>★</button><button on:click={()=>use(item)}>{item.name}</button><small>{item.category} · {item.visibility} · {item.license}{recents.includes(item.id)?' · recent':''}</small></li>{/each}{#each [...$editor.document.resources,...$editor.document.fonts].filter(item=>item.name.toLowerCase().includes(query.toLowerCase())) as item}<li><span>▧</span><strong>{item.name}</strong><small>{item.mimeType} · embedded/private</small></li>{/each}</ul></section>
<style>section{padding:.75rem;border-top:1px solid #ddd}h2{font-size:.8rem;text-transform:uppercase}.actions{display:flex;gap:.3rem;flex-wrap:wrap}.actions label{border:1px solid #bbb;padding:.3rem}.actions input{position:absolute;opacity:0;width:1px}ul{list-style:none;padding:0}li{display:grid;grid-template-columns:auto 1fr;gap:.2rem}.star{grid-row:span 2}small{color:#666}</style>
